import type { Source } from "./Core";
/**
 * Callbag factory that concatenates the data from multiple (2 or more)
 * callbag sources. It starts each source one at a time: waits for the previous
 * source to end before starting the next source. Works with both pullable
 * and listenable sources.
 *
 * Adapted from https://github.com/staltz/callbag-concat
 *
 * Marble diagram:
 *   "-a-b-c-|"
 *          "-d-e-f-|"
 *   {concat}
 *   "-a-b-c--d-e-f-|"
 *
 * @param sources The callbag sources to concatenate.
 *
 * @internal
 */
export declare const concat: <T, E>(...sources: Source<T, E>[]) => Source<T, E>;
